import sqlite3

database = sqlite3.connect(":memory:")
database.executescript("""
    CREATE TABLE events (event_id TEXT PRIMARY KEY, payload INTEGER NOT NULL CHECK(payload >= 0));
    CREATE TABLE checkpoint (singleton INTEGER PRIMARY KEY CHECK(singleton = 1), position INTEGER NOT NULL);
    INSERT INTO checkpoint VALUES (1, 0);
""")


def apply_batch(rows, crash=False):
    if not rows:
        return
    with database:
        for offset, event_id, payload in rows:
            stored = database.execute(
                "SELECT payload FROM events WHERE event_id=?", (event_id,)
            ).fetchone()
            if stored is not None and stored[0] != payload:
                raise ValueError("Conflicting immutable payload")
            if stored is None:
                database.execute(
                    "INSERT INTO events VALUES (?, ?)", (event_id, payload)
                )
        if crash:
            raise RuntimeError("Injected failure before checkpoint")
        database.execute(
            "UPDATE checkpoint SET position=max(position, ?) WHERE singleton=1",
            (max(row[0] for row in rows),),
        )


batch = [(1, "A", 10), (2, "B", 20)]
try:
    apply_batch(batch, crash=True)
except RuntimeError:
    pass
rolled_back = database.execute("SELECT count(*) FROM events").fetchone()[0]
initial_offset = database.execute("SELECT position FROM checkpoint").fetchone()[0]
apply_batch(batch)
apply_batch(batch)
conflict = 0
try:
    apply_batch([(3, "A", 99)])
except ValueError:
    conflict = 1
stored_rows = database.execute("SELECT count(*) FROM events").fetchone()[0]
final_offset = database.execute("SELECT position FROM checkpoint").fetchone()[0]
database.close()
print(rolled_back, initial_offset, stored_rows, final_offset, conflict)

from statistics import mean

versions = [
    dict(day=1, available=2, revision=1, value=10.0),
    dict(day=1, available=5, revision=2, value=12.0),
    dict(day=2, available=3, revision=1, value=20.0),
]


def snapshot(target_day, asof):
    latest = {}
    for event in sorted(versions, key=lambda row: (row["available"], row["revision"])):
        if target_day - 7 <= event["day"] < target_day and event["available"] <= asof:
            latest[event["day"]] = event
    return latest


historical = snapshot(4, 4)
corrected = snapshot(4, 6)
assert historical[1]["value"] == 10 and corrected[1]["value"] == 12
print(
    mean(row["value"] for row in historical.values()),
    mean(row["value"] for row in corrected.values()),
    len(historical),
)

